<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';const props=defineProps<{patterns:any[]}>();const emit=defineEmits(['pattern']);const all=ref<any[]>([]),selection=ref(''),hover=ref('');const groups=computed(()=>{const result=new Map<string,any>();for(const g of all.value){const name=g.name.replace(/〔.*?〕/g,'').trim(),key=g.code+'|'+name;if(!g.code.startsWith('C-'))continue;if(!result.has(key))result.set(key,{key,code:g.code,name,patterns:[]});if(!result.get(key).patterns.includes(g.pattern))result.get(key).patterns.push(g.pattern)}return Array.from(result.values()).filter(g=>g.patterns.length>1).sort((a,b)=>b.patterns.length-a.patterns.length)});const group=computed(()=>groups.value.find(g=>g.key===selection.value)||groups.value[0]);const nodes=computed(()=>{const ps=group.value?.patterns.slice(0,16)||[];return ps.map((id:string,i:number)=>{const p=props.patterns.find(p=>p.id===id),theta=(i/ps.length)*Math.PI*2-Math.PI/2;return {...p,x:400+Math.cos(theta)*230,y:300+Math.sin(theta)*220}})});onMounted(async()=>{try{const r=await fetch('/api/genes');all.value=await r.json()}catch{}});
</script><template><section class="shared-patterns"><div class="section-title"><div><p class="kicker">A COMMON RHYTHM / 跨纹样的构图语言</p><h2>同一种秩序，<em>不同的表达。</em></h2><p class="muted">按相同构图编码与名称，探索资料中的复用样本。共享编码不等于已经证明历史同源。</p></div><select aria-label="选择共享构图基因" v-model="selection"><option value="" disabled>选择一种构图</option><option v-for="g in groups" :value="g.key">{{g.name}} · {{g.patterns.length}} 篇</option></select></div><div class="shared-layout"><svg viewBox="0 0 800 600" aria-label="共享构图的纹样分布图"><circle class="shared-orbit" cx="400" cy="300" r="220"/><circle class="shared-orbit" cx="400" cy="300" r="155"/><g v-for="p in nodes" :key="p.id" @mouseenter="hover=p.id" @mouseleave="hover=''"><path :class="{lit:hover===p.id}" :d="`M400 300 Q${(p.x+400)/2} ${p.y} ${p.x} ${p.y}`"/><g :transform="`translate(${p.x} ${p.y})`" role="button" tabindex="0" :aria-label="p.name" @click="emit('pattern',p.id)" @keydown.enter="emit('pattern',p.id)"><circle r="24"/><text y="5">{{p.name.slice(0,1)}}</text><text class="shared-name" y="43">{{p.name.length>9?p.name.slice(0,9)+'…':p.name}}</text><text class="shared-id" y="58">{{p.id}}</text></g></g><circle class="shared-center" cx="400" cy="300" r="70"/><text class="shared-center-title" x="400" y="295">{{group?.name}}</text><text class="shared-center-code" x="400" y="322">{{group?.code}}</text></svg><aside><span class="shared-count">{{group?.patterns.length||0}}<small>篇资料复用此构图</small></span><h3>变化之中，<br>仍有可辨的秩序。</h3><p>同一个构图规则，可以组织不同的花形、几何或动物图元。点击外围样本，比较它们如何安排中心、轴线与留白。</p><p class="muted">仅汇集编码及名称一致的条目；同码异名的冲突不据此合并。图中最多展示16个样本。</p></aside></div></section></template>
